          title: "Java Entities, Inverted Index ER Diagram & Observability APIs",
          code: "/*\n * ============================================================================\n * ASCII ENTITY-RELATIONSHIP (ER) DIAGRAM (TSDB INVERTED INDEX & CHUNKS)\n * ============================================================================\n *\n * +-------------------------+       1           1..* +--------------------------+\n * |     LabelPosting        |------------------------|       TimeSeries         |\n * | (Inverted Index Bitmap) |                        +--------------------------+\n * +-------------------------+                        | PK tenantId (String)     |\n * | PK tenantId (String)    |                        | PK seriesId (Long xxHash)|\n * | PK labelName (String)   |                        |    metricName (String)   |\n * | PK labelValue (String)  |                        |    canonicalLabels (JSON)|\n * |    roaringBitmap (Bytes)|                        |    createdAt (Instant)   |\n * +-------------------------+                        +------------+-------------+\n *   e.g. (\"service\",\"auth\") -> [series 101, 204, 899]             | 1\n *        (\"status\",\"500\")   -> [series 204, 512]                  |\n *        BITMAP AND         => [series 204]                       v 1..*\n *                                                    +--------------------------+\n * +-------------------------+                        |       GorillaChunk       |\n * |        AlertRule        |                        +--------------------------+\n * +-------------------------+                        | PK seriesId (Long)       |\n * | PK ruleId (UUID)        |                        | PK minTimeMs (Long)      |\n * |    tenantId (String)    |                        |    maxTimeMs (Long)      |\n * |    promQlExpr (String)  |                        |    sampleCount (Short)   |\n * |    forDurationSec (Int) |                        |    xorBitStream (byte[]) |\n * |    state (OK/PENDING/   |                        +--------------------------+\n * |           FIRING)       |\n * +-------------------------+\n */\n\npackage com.observability.telemetry.domain;\n\nimport java.nio.charset.StandardCharsets;\nimport java.util.*;\n\npublic record Label(String name, String value) implements Comparable<Label> {\n    @Override\n    public int compareTo(Label o) {\n        int cmp = this.name.compareTo(o.name);\n        return (cmp != 0) ? cmp : this.value.compareTo(o.value);\n    }\n}\n\npublic record Sample(long timestampMs, double value) {}\n\npublic record TimeSeriesBatch(\n    String tenantId,\n    String metricName,\n    List<Label> labels,\n    List<Sample> samples\n) {\n    // Computes deterministic 64-bit FNV-1a / xxHash fingerprint from sorted canonical labels\n    public long computeSeriesId() {\n        List<Label> sorted = new ArrayList<>(labels);\n        Collections.sort(sorted);\n        long hash = 0xcbf29ce484222325L;\n        hash = fnv1a(hash, metricName);\n        for (Label l : sorted) {\n            hash = fnv1a(hash, l.name());\n            hash = fnv1a(hash, l.value());\n        }\n        return hash;\n    }\n\n    private static long fnv1a(long hash, String str) {\n        byte[] bytes = str.getBytes(StandardCharsets.UTF_8);\n        for (byte b : bytes) {\n            hash ^= (b & 0xff);\n            hash *= 0x100000001b3L;\n        }\n        return hash;\n    }\n}\n\npublic record LogStreamBatch(\n    String tenantId,\n    Map<String, String> streamLabels, // Low-cardinality: service, env, region, level\n    List<LogLine> entries\n) {\n    public record LogLine(long timestampNs, String traceId, String messageJson) {}\n}\n\n// REST / gRPC Gateway Signatures\npackage com.observability.telemetry.api;\n\nimport com.observability.telemetry.domain.*;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\nimport java.util.List;\n\n@RestController\n@RequestMapping(\"/v1\")\npublic interface TelemetryApi {\n\n    record WriteMetricsRequest(List<TimeSeriesBatch> series) {}\n    record QueryRangeResponse(long seriesId, List<Label> labels, List<Sample> values) {}\n\n    @PostMapping(\"/metrics/write\")\n    ResponseEntity<Void> ingestMetrics(\n        @RequestHeader(\"X-Tenant-Id\") String tenantId,\n        @RequestBody WriteMetricsRequest batch\n    );\n\n    @PostMapping(\"/logs/write\")\n    ResponseEntity<Void> ingestLogs(\n        @RequestHeader(\"X-Tenant-Id\") String tenantId,\n        @RequestBody List<LogStreamBatch> streams\n    );\n\n    @GetMapping(\"/metrics/query_range\")\n    ResponseEntity<List<QueryRangeResponse>> queryRange(\n        @RequestHeader(\"X-Tenant-Id\") String tenantId,\n        @RequestParam String query,\n        @RequestParam long startMs,\n        @RequestParam long endMs,\n        @RequestParam int stepSec\n    );\n}"
