    tradeOffs: [
      {
        option: "Custom Gorilla TSDB + Label-Only Log Indexing (Mimir + Loki / ClickHouse)",
        pros: "10–12x storage compression, immune to full-text index write amplification on logs, and seamless horizontal scaling backed by cheap S3 object storage.",
        cons: "Needle-in-a-haystack unindexed regex log searches across multi-TB windows require parallel brute-force chunk scanning (mitigated via Bloom filters and ClickHouse sparse primary indexes).",
        bestFor: "High-volume cloud infrastructure metrics and container logs where cost per TB and write throughput dominate."
      },
      {
        option: "Full-Text Inverted Index for Everything (Elasticsearch / OpenSearch)",
        pros: "Sub-second arbitrary keyword and tokenized phrase search across every JSON field in logs.",
        cons: "Inverted index is often larger than the raw log data itself (1.2x–2x storage amplification), high JVM heap/GC pressure, and expensive shard rebalancing during traffic spikes.",
        bestFor: "Low-to-medium volume security SIEM logs or business audit events requiring ad-hoc full-text faceted search."
      },
      {
        option: "Push vs. Pull (Prometheus Scrape) Ingestion Model",
        pros: "Pull lets the TSDB control scrape pacing and automatically detects target liveness (`up == 0`); Push works seamlessly across NAT gateways, serverless functions (AWS Lambda), and ephemeral short-lived jobs.",
        cons: "Pure Pull struggles across multi-VPC firewalls; pure Push requires edge rate-limiting and Distributor load balancers to prevent thundering herds.",
        bestFor: "Hybrid architecture: local host DaemonSet scrapes pods locally (Pull) and forwards compressed OTLP batches to the central regional Distributor (Push)."
      }
    ],
    interviewTip: "Interviewers love when you contrast **Metrics** vs. **Logs** storage internals: explain that Metrics use an **Inverted Index (`Label -> RoaringBitmap<SeriesId>`) + Gorilla XOR chunks** (where 16-byte samples shrink to `1.37 bytes`), whereas modern Logs (Loki/ClickHouse) avoid full-text indexing every word and instead index only low-cardinality labels + per-chunk **Bloom Filters** over Zstd-compressed columnar blocks on S3."
